package com.bank.flink.rs;

import java.util.List;

// Fixed-delay: up to maxAttempts restarts, constant delay each time.
class FixedDelayStrategy implements RestartStrategy {
    private final int maxAttempts;
    private final long delayMillis;

    FixedDelayStrategy(int maxAttempts, long delayMillis) {
        this.maxAttempts = maxAttempts;
        this.delayMillis = delayMillis;
    }

    @Override
    public long decide(List<Failure> history, Failure current) {
        int attemptsUsed = history.size(); // failures before this one
        if (attemptsUsed >= maxAttempts) return -1; // exhausted -> terminal
        return delayMillis;
    }

    @Override
    public String name() { return "fixed-delay(" + maxAttempts + ", " + delayMillis + "ms)"; }
}
