package com.bank.flink.rs;

import java.util.List;

// Failure-rate: restart freely unless failures within the interval exceed max.
class FailureRateStrategy implements RestartStrategy {
    private final int maxFailuresPerInterval;
    private final long intervalMillis;
    private final long delayMillis;

    FailureRateStrategy(int maxFailuresPerInterval, long intervalMillis, long delayMillis) {
        this.maxFailuresPerInterval = maxFailuresPerInterval;
        this.intervalMillis = intervalMillis;
        this.delayMillis = delayMillis;
    }

    @Override
    public long decide(List<Failure> history, Failure current) {
        long windowStart = current.getTimestampMillis() - intervalMillis;
        long inWindow = history.stream()
                .filter(f -> f.getTimestampMillis() >= windowStart)
                .count() + 1; // include current
        if (inWindow > maxFailuresPerInterval) return -1; // too many -> terminal
        return delayMillis;
    }

    @Override
    public String name() {
        return "failure-rate(" + maxFailuresPerInterval + "/" + intervalMillis + "ms)";
    }
}
