package com.bank.flink.rs;

import java.util.List;

// Exponential-delay: backoff doubles each consecutive failure up to a cap.
class ExponentialDelayStrategy implements RestartStrategy {
    private final long initialMillis;
    private final double multiplier;
    private final long maxMillis;

    ExponentialDelayStrategy(long initialMillis, double multiplier, long maxMillis) {
        this.initialMillis = initialMillis;
        this.multiplier = multiplier;
        this.maxMillis = maxMillis;
    }

    @Override
    public long decide(List<Failure> history, Failure current) {
        int consecutive = history.size(); // simplistic: all are consecutive here
        double delay = initialMillis * Math.pow(multiplier, consecutive);
        return (long) Math.min(delay, maxMillis); // never terminal (keeps trying)
    }

    @Override
    public String name() {
        return "exponential-delay(init=" + initialMillis + "ms x" + multiplier + ")";
    }
}
