package com.bank.flink.rs;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Applies a strategy to a sequence of failures and logs each decision.
class JobSupervisor {
    private static final Logger log = Logger.getLogger(JobSupervisor.class.getName());

    private final RestartStrategy strategy;
    private final List<Failure> history = new ArrayList<>();

    JobSupervisor(RestartStrategy strategy) {
        this.strategy = strategy;
    }

    boolean onFailure(Failure f) {
        long decision = strategy.decide(history, f);
        history.add(f);
        if (decision < 0) {
            log.severe(() -> strategy.name() + " -> FAIL TERMINALLY after " + history.size()
                    + " failures (" + f.getReason() + ")");
            return false;
        }
        log.info(() -> strategy.name() + " -> RESTART after " + decision
                + "ms (failure #" + history.size() + ": " + f.getReason() + ")");
        return true;
    }
}
