package com.bank.flink.rs;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: feed a burst of failures through all four strategies.
public class RestartStrategyDemo {
    private static final Logger log = Logger.getLogger(RestartStrategyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new RsLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Five failures over ~2 minutes.
        Failure[] failures = {
            new Failure(0,       "TaskManager lost"),
            new Failure(20_000,  "Kafka timeout"),
            new Failure(40_000,  "Kafka timeout"),
            new Failure(60_000,  "DB connection reset"),
            new Failure(80_000,  "DB connection reset")
        };

        runStrategy(new FixedDelayStrategy(3, 10_000), failures);
        runStrategy(new FailureRateStrategy(3, 300_000, 10_000), failures);
        runStrategy(new ExponentialDelayStrategy(1_000, 2.0, 60_000), failures);
        runStrategy(new NoRestartStrategy(), failures);
    }

    private static void runStrategy(RestartStrategy strategy, Failure[] failures) {
        log.info(() -> "=== Strategy: " + strategy.name() + " ===");
        JobSupervisor supervisor = new JobSupervisor(strategy);
        for (Failure f : failures) {
            if (!supervisor.onFailure(f)) break; // terminal
        }
    }
}

